        null,
        gp('M8 4.5v8'),
        gp('M8 4.5C6.6 3.4 4.8 3.2 3 3.6v7.6c1.8-.4 3.6-.2 5 .9'),
        gp('M8 4.5c1.4-1.1 3.2-1.3 5-.9v7.6c-1.8-.4-3.6-.2-5 .9')
